```css
/* ============================================
   DESIGN SYSTEM TOKENS
   ============================================ */
:root {
    /* Colors - Bloomberg Terminal Inspired */
    --color-bg-primary: #0a0a0a;
    --color-bg-secondary: #141414;
    --color-bg-tertiary: #1a1a1a;

    --color-accent-teal: #00d4aa;
    --color-accent-amber: #f5a623;
    --color-accent-red: #ff4444;

    --color-text-primary: #e8e8e8;
    --color-text-secondary: #a0a0a0;
    --color-text-tertiary: #666666;

    --color-border: #2a2a2a;
    --color-border-active: var(--color-accent-teal);

    /* Sentiment Colors */
    --color-sentiment-positive: var(--color-accent-teal);
    --color-sentiment-neutral: var(--color-accent-amber);
    --color-sentiment-negative: var(--color-accent-red);

    /* Typography */
    --font-primary: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    --font-mono: "SF Mono", "Consolas", "Monaco", monospace;

    --font-size-xs: 0.75rem;
    --font-size-sm: 0.875rem;
    --font-size-base: 1rem;
    --font-size-lg: 1.25rem;
    --font-size-xl: 1.5rem;

    /* Spacing */
    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;

    /* Layout */
    --header-height: 60px;
    --sidebar-width: 380px;
    --sentiment-height: 180px;

    /* Animation */
    --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

    /* Z-index Scale */
    --z-base: 1;
    --z-overlay: 10;
    --z-modal: 100;
    --z-tooltip: 1000;
}

/* High Contrast Mode Override */
body.high-contrast {
    --color-bg-primary: #000000;
    --color-text-primary: #ffffff;
    --color-border: #ffffff;
}

/* Reduced Motion Override */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* ============================================
   BASE STYLES
   ============================================ */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-primary);
    background: var(--color-bg-primary);
    color: var(--color-text-primary);
    line-height: 1.6;
    overflow-x: hidden;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}
